import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../api/axios';
import styles from './MovieDetails.module.css';

export default function MovieDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [movie, setMovie] = useState(null);

  useEffect(() => {
    api.get(`/movies/${id}`).then(({ data }) => setMovie(data)).catch(console.error);
  }, [id]);

  if (!movie) return <p className={styles.loading}>Loading...</p>;

  return (
    <div className={styles.container}>
      <div className={styles.hero}>
        <img
          src={movie.posterUrl || 'https://via.placeholder.com/300x450?text=No+Poster'}
          alt={movie.title}
          className={styles.poster}
        />
        <div className={styles.info}>
          <h1>{movie.title}</h1>
          <p className={styles.meta}>
            {movie.genre?.join(', ')} • {movie.language} • {movie.duration} min
          </p>
          <p className={styles.rating}>⭐ {movie.rating}/10</p>
          {movie.director && <p><strong>Director:</strong> {movie.director}</p>}
          {movie.cast?.length > 0 && <p><strong>Cast:</strong> {movie.cast.join(', ')}</p>}
          <p className={styles.description}>{movie.description}</p>
          <button className={styles.btn} onClick={() => navigate(`/movies/${id}/showtimes`)}>
            Book Tickets
          </button>
        </div>
      </div>
    </div>
  );
}
